      "content": "{\n  \"name\": \"dsh-better-workspace\",\n  \"version\": \"0.43.0\",\n  \"description\": \"侧边栏工作区树:按官方磁盘目录嵌套(官方 workspace-tree 语义),可选按名称中的 / 分组(默认关闭,设置里开启);新会话页的工作区选择器同树(同一份视图选项即时同步);添加工作区走官方目录流。Workspace tree for the DSH sidebar: disk-path nesting (official workspace-tree semantics), with optional \\\"/\\\"-name grouping (off by default), and the same tree in the New Session workspace picker; add-workspace rides the official directory flow.\",\n  \"type\": \"module\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/KannaKuron/dsh-better-workspace.git\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"main\": \"src/index.js\",\n  \"exports\": {\n    \".\": \"./src/index.js\",\n    \"./client\": \"./src/client.js\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"engines\": {\n    \"node\": \">=24.9.0\",\n    \"dsh\": \">=0.2.2-rc.1\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-modules\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-ui-context-menu\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"src/index.js\",\n    \"src/client.js\",\n    \"src/client.locales.js\",\n    \"src/client.styles.js\",\n    \"src/title-source.js\",\n    \"cordis.patch.yml\",\n    \"dsh.plugin.json\",\n    \"README.md\",\n    \"README_EN.md\",\n    \"LICENSE\",\n    \"locale\",\n    \"icon.svg\"\n  ],\n  \"scripts\": {\n    \"test\": \"node --test tests/smoke.mjs\",\n    \"version\": \"node -e \\\"const fs=require('fs');const m=JSON.parse(fs.readFileSync('dsh.plugin.json','utf8'));const v=JSON.parse(fs.readFileSync('package.json','utf8')).version;m.version=v;fs.writeFileSync('dsh.plugin.json',JSON.stringify(m,null,2)+'\\\\n')\\\" && git add dsh.plugin.json\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"sidebar\",\n    \"workspace\",\n    \"dsh-better\"\n  ],\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh\": \">=0.2.2-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.19.0\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh\": {\n      \"optional\": true\n    }\n  },\n  \"homepage\": \"https://github.com/KannaKuron/dsh-better-workspace\",\n  \"bugs\": {\n    \"url\": \"https://github.com/KannaKuron/dsh-better-workspace/issues\"\n  },\n  \"icon\": \"./icon.svg\",\n  \"devDependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.19.0\",\n    \"zod\": \"^4.4.3\"\n  }\n}\n"
