    {
      "path": "src/title-source.js",
      "content": "/**\n * Title provenance: the host knows WHY a session title exists — the\n * `session/title` event carries `source.kind` (`fallback` | `provider` |\n * `user`), and the official title projection deliberately exposes only the\n * plain string. Without the source, the sidebar can only guess from the text\n * whether a `/` was a deliberate grouping or part of an auto-generated\n * sentence (issue #19). This optional summary projection carries the kind to\n * the list rows so the client can trust intent instead of guessing it.\n *\n * It is a separate module so the fold can be unit-tested without booting the\n * plugin row. Registration is best-effort: when zod is unavailable (a profile\n * that did not hoist the host's dependency), the client keeps its display-layer\n * fallback and the plugin still mounts.\n */\nexport const TITLE_SOURCE_KEY = 'betterWorkspace/titleSource'\n\n/**\n * Build the projection definition. `z` is zod's namespace, injected so the\n * fold can be tested with a real schema without a top-level import.\n * @param z - zod namespace (v4).\n * @returns a summary projection definition for `sessionProjections.register`.\n */\nexport function titleSourceProjection(z) {\n  const schema = z.string().nullable()\n  return {\n    key: TITLE_SOURCE_KEY,\n    stateVersion: 1,\n    stateSchema: schema,\n    init: () => null,\n    apply: (state, event) => {\n      if (!event || event.type !== 'session/title') return state\n      const kind = event.data && event.data.source && event.data.source.kind\n      return typeof kind === 'string' && kind !== '' ? kind : state\n    },\n    // A summary unit by default: the list row needs this value. Eager\n    // providers must stay cheap; this fold only reads session/title events.\n    wire: { viewSchema: schema, view: (state) => state },\n  }\n}\n\n/**\n * Register the projection on the plugin context. Never throws: a missing zod\n * or a registration conflict degrades to the client's text fallback.\n * @param ctx - the plugin host context carrying `sessionProjections`.\n * @param log - diagnostic sink.\n * @returns whether the projection was registered.\n */\nexport async function registerTitleSource(ctx, log = () => {}) {\n  let z\n  try {\n    ({ z } = await import('zod'))\n  } catch (error) {\n    log('[dsh-better-workspace] zod is not resolvable; session title provenance falls back to display heuristics: '\n      + (error && error.message || String(error)))\n    return false\n  }\n  try {\n    await ctx.sessionProjections.register(titleSourceProjection(z))\n    return true\n  } catch (error) {\n    log('[dsh-better-workspace] title provenance projection was not registered; '\n      + 'session titles fall back to display heuristics: ' + (error && error.message || String(error)))\n    return false\n  }\n}\n"
    },
    {
      "path": "src/client.js",
      "content": "/**\n * dsh-better-workspace — client half (plain JavaScript, no build step).\n *\n * Registrations:\n *  1. sidebar.workspaces (priority -1): replaces the shipped workspace\n *     browser with a two-layer hierarchy — disk nesting (a workspace row\n *     nests under its nearest registered ancestor directory, the official\n *     workspace-tree semantics) plus \"/\"-segment name groups inside each\n *     level (this plugin's founding feature). The registration neither\n *     declares nor occupies the sidebar.workspaces.directoryFlow child hole:\n *     the official entry keeps the declaration and the add-workspace flow\n *     reads its occupant from the slot ledger.\n *  2. plugins.bundle.config (the Plugins panel's bundle page, keyed by\n *     package name): the settings card — the only settings seat.\n *\n * Every require below is a dsh client baseline module (see\n * @deepseek-ai/dsh-client-web seed.ts): react, @deepseek-ai/dsh-client-store,\n * @deepseek-ai/dsh-client-ui-primitives.\n */\nwindow.__ModuleLoader__.load({\n  id: 'dsh-better-workspace',\n  factory: (require) => {\n    const React = require('react')\n    const storeKit = require('@deepseek-ai/dsh-client-store')\n    const ui = require('@deepseek-ai/dsh-client-ui-primitives')\n\n    const E = React.createElement\n    const NS = 'betterWorkspace'\n    // Official transient banner (rc.1 primitives Toast; body portal,\n    // self-fading). If the primitives family has no Toast, the\n    // copy-session-id notice falls back to this plugin's own chip.\n    const officialToast = typeof ui.Toast === 'function' ? ui.Toast : null\n\n    /* ============================== i18n ============================== */\n    // All dictionaries ship in the package-local chunk client.locales.js.\n    // apply() awaits it once (require.async) before registering NS.\n    let localeTables = null\n\n    /* ============================= helpers ============================ */\n\n    const cls = (...xs) => xs.filter(Boolean).join(' ')\n    const messageOf = (reason) => (reason instanceof Error ? reason.message : String(reason))\n\n    const basename = (p) => {\n      if (!p) return ''\n      const s = String(p).replace(/[\\\\/]+$/, '')\n      const i = Math.max(s.lastIndexOf('/'), s.lastIndexOf('\\\\'))\n      return i === -1 ? s : s.slice(i + 1)\n    }\n\n    // Host-recorded title provenance (src/title-source.js). A fresh session's\n    // fallback/provider title never becomes a hierarchy; only a user rename or\n    // an explicit grouping action may form groups. Undefined means the host\n    // projection is not there (old cold cache), so the display falls back to\n    // the text heuristics below.\n    const TITLE_SOURCE_KEY = 'betterWorkspace/titleSource'\n    const titleSourceOf = (summary) => {\n      const values = summary && summary.projectionValues\n      return values && typeof values === 'object' ? values[TITLE_SOURCE_KEY] : undefined\n    }\n    const groupsAllowedFor = (summary) => {\n      const source = titleSourceOf(summary)\n      return source === undefined || source === 'user'\n    }\n    /**\n     * Plain-text splitting with the URL tail kept opaque: a bare \"/\" split\n     * shreds URLs (\"https:\" → empty → host → path...), so from the first\n     * \"://\" onward the tail is ONE leaf; text before the marker splits\n     * normally at the last \"/\" before it. This is the FALLBACK guard —\n     * whether a session title is allowed to form groups at all is decided by\n     * its host-recorded provenance (see TITLE_SOURCE_KEY), not by the text.\n     */\n    const splitPlainSegs = (text) => {\n      const s = String(text || '')\n      const schemeAt = s.indexOf('://')\n      if (schemeAt === -1) return s.split('/').map(x => x.trim()).filter(Boolean)\n      const cut = s.lastIndexOf('/', schemeAt)\n      const segs = (cut === -1 ? '' : s.slice(0, cut)).split('/').map(x => x.trim()).filter(Boolean)\n      const tail = s.slice(cut + 1).trim()\n      if (tail !== '') segs.push(tail)\n      return segs\n    }\n\n    /**\n     * A title that QUOTES an absolute path is a sentence, not a name\n     * hierarchy (v0.37.2, issue #17): the host auto-titles a new session by\n     * echoing its first message verbatim, so \"/Users/x/repo/file.md\" used to\n     * shred into one fake folder per segment. Detection stays narrow on\n     * purpose — a token starts at line start / whitespace with \"/\" (or a\n     * \"C:/\" drive form) and carries at least one more \"/\" — so plain name\n     * groups (\"web/前端\") and relative pairs (\"a/b\") keep splitting.\n     */\n    const titleQuotesPath = (text) => {\n      // A path inside a PAIRED quote span is already an opaque leaf (the\n      // quote parser below keeps it verbatim), so only the unquoted remainder\n      // can be mistaken for a name hierarchy. \"~/.dsh/...\" and \"./...\" are\n      // paths even when they carry only one slash; drive-letter paths are\n      // paths by construction. A bare \"https://\" is not matched (it does not\n      // start with a slash).\n      const s = String(text || '').replace(/\"[^\"]*\"|“[^”]*”/g, ' ')\n      const re = /(?:^|\\s)(?:(?:[A-Za-z]:)?\\/\\S+|(?:~|\\.{1,2})\\/\\S+)/g\n      let m\n      while ((m = re.exec(s)) !== null) {\n        const token = m[0].trim()\n        if (/^[A-Za-z]:[\\\\/]/.test(token)) return true\n        if (/^(?:~|\\.{1,2})\\//.test(token)) return true\n        if ((token.match(/\\//g) || []).length >= 2) return true\n      }\n      return false\n    }\n\n    /**\n     * Title → hierarchy segments, QUOTE-AWARE: a PAIRED “…” (or \"…\") span is\n     * verbatim — slashes inside quotes never split, the quotes stay part of\n     * the leaf. Text outside paired spans splits through splitPlainSegs\n     * (URL-tail opaque). A LONE quote character — an opener with no matching\n     * closer, or a closer without an opener — is an ORDINARY character and\n     * splits normally around it (0.9.1 swallowed the tail after an\n     * unterminated opener; the user wants lone quotes as plain text).\n     * Grouping is a pure projection, so previously shredded titles re-flow\n     * on reload.\n     */\n    const splitTitleSegs = (title, allowGroups = true) => {\n      const s = String(title || '')\n      if (allowGroups === false) return s.trim() === '' ? [] : [s.trim()]\n      if (titleQuotesPath(s)) return [s.trim()]\n      if (!/[\"“]/.test(s)) return splitPlainSegs(s)\n      const out = []\n      let plain = ''\n      let i = 0\n      while (i < s.length) {\n        const ch = s[i]\n        if (ch === '\"' || ch === '“') {\n          const close = ch === '“' ? '”' : '\"'\n          const j = s.indexOf(close, i + 1)\n          if (j === -1) { // lone opener: ordinary character, keep scanning\n            plain += ch\n            i += 1\n            continue\n          }\n          const end = j + 1\n          const quoted = s.slice(i, end).trim()\n          // Quotes protect a slash INSIDE a leaf; they do not manufacture a\n          // group out of ordinary punctuation. \"受阻\" in a sentence stays\n          // part of the surrounding leaf (issue #19), so the pending plain\n          // text is only flushed when the quoted span itself carries a slash.\n          if (quoted !== '' && quoted.includes('/')) {\n            for (const seg of splitPlainSegs(plain)) out.push(seg)\n            plain = ''\n            out.push(quoted)\n          } else {\n            plain += quoted\n          }\n          i = end\n          continue\n        }\n        plain += ch\n        i += 1\n      }\n      for (const seg of splitPlainSegs(plain)) out.push(seg)\n      return out\n    }\n    const normPath = (p) => splitTitleSegs(p).join('/')\n\n    /**\n     * Resolve one configured icon value to a glyph the LOADED primitives\n     * actually export (pure). The current icon set uses stroke-weight names\n     * (…Regular / …Medium) while persisted choices from older plugin releases\n     * carry pi